sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_comp(uv);return float4(0.0); }
uniform float2 amzp_lightPos;
uniform float amzp_lightH;
layout(color) uniform half4 amzp_lightCol;
uniform float amzp_intensity;
uniform float amzp_ambient;
uniform float amzp_falloffR;
uniform float amzp_relief;
uniform float amzp_specular;
uniform float amzp_shine;
uniform float amzp_shadow;
uniform float amzp_shadowSoft;
uniform float amzp_quality;
uniform float amzp_depthSrc;
uniform float amzp_invertDepth;
uniform float amzp_depthSmooth;
uniform float amzp_showDepth;
uniform float amzp_overdrawOn;
    float2 SS;
    float PXS;
    void dpInit() { SS = max(screen.zw, float2(1.0)); PXS = screen.zw.x / max(screen.zw.x, 1.0); }
    float4 colRaw(float2 uv) { uv = clamp(uv, float2(0.0), float2(1.0)); return int(amzp_depthSrc) == 0 ? amzTexture(1, uv) : amzTexture(0, uv); }
    float depRaw(float2 uv) {
        uv = clamp(uv, float2(0.0), float2(1.0));
        float4 c = int(amzp_depthSrc) == 0 ? amzTexture(0, uv) : amzTexture(1, uv);
        float3 u = c.a > 0.0001 ? c.rgb / c.a : float3(0.0);
        float d = dot(u, float3(0.299, 0.587, 0.114));
        return (amzp_invertDepth>0.5) ? 1.0 - d : d;
    }
    float dep(float2 uv) {
        float r = amzp_depthSmooth * PXS;
        if (r < 0.5) return depRaw(uv);
        float2 o = r / SS;
        float s = depRaw(uv) * 2.0;
        s += depRaw(uv + float2(o.x, 0.0)) + depRaw(uv - float2(o.x, 0.0)) + depRaw(uv + float2(0.0, o.y)) + depRaw(uv - float2(0.0, o.y));
        s += 0.7 * (depRaw(uv + o) + depRaw(uv - o) + depRaw(uv + float2(o.x, -o.y)) + depRaw(uv + float2(-o.x, o.y)));
        return s / 8.8;
    }
    float lum(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    void nmFxMain() {
        float2 p = amzScreenNorm();
        float4 c = colRaw(p);
        float3 base = c.a > 0.0001 ? c.rgb / c.a : float3(0.0);
        float hp = amzp_relief * PXS;
        float2 e = 1.5 / SS;
        float dx = (dep(p + float2(e.x, 0.0)) - dep(p - float2(e.x, 0.0))) * hp / 3.0;
        float dy = (dep(p + float2(0.0, e.y)) - dep(p - float2(0.0, e.y))) * hp / 3.0;
        float3 n = normalize(float3(-dx, -dy, 1.0));
        float4 lc = float4(0.5, 0.5, 0.0, 1.0) * amzLayerToScreen();
        float2 lpx = lc.xy * SS + float2(amzp_lightPos.x, -amzp_lightPos.y) * PXS;
        float2 ppx = p * SS;
        float zp = dep(p) * hp;
        float3 L3 = float3(lpx - ppx, amzp_lightH * PXS - zp);
        float dist = length(L3);
        float3 L = L3 / max(dist, 1e-4);
        float dif = max(dot(n, L), 0.0);
        float3 hv = normalize(L + float3(0.0, 0.0, 1.0));
        float sp = pow(max(dot(n, hv), 0.0), max(amzp_shine, 1.0)) * amzp_specular;
        float att = amzp_falloffR > 0.0 ? 1.0 / (1.0 + pow(dist / max(amzp_falloffR * PXS, 1.0), 2.0)) : 1.0;
        float sh = 1.0;
        if (amzp_shadow > 0.0 && L3.z > 0.0) {
            float N = amzp_quality < 1.5 ? 16.0 : (amzp_quality < 2.5 ? 24.0 : (amzp_quality < 3.5 ? 32.0 : (amzp_quality < 4.5 ? 48.0 : 64.0)));
            float2 dir2 = L3.xy;
            float len2 = length(dir2);
            float maxD = min(len2, hp * 6.0 + 40.0);
            float occ = 0.0;
            for (int i = 1; i <= 64; i++) {
                float fi = float(i);
                if (fi > N) break;
                float tt = fi / N;
                float sdist = maxD * tt * tt;
                float2 q = ppx + (len2 > 1e-3 ? dir2 / len2 : float2(0.0)) * sdist;
                float rayZ = zp + L3.z * (sdist / max(len2, 1e-3));
                float surf = dep(q / SS) * hp;
                float soft = max(amzp_shadowSoft * 40.0 * PXS * tt + 0.5, 0.5);
                occ = max(occ, smoothstep(-soft, soft, surf - rayZ));
            }
            sh = 1.0 - occ * clamp(amzp_shadow, 0.0, 1.0);
        }
        float3 lit = base * (amzp_ambient + dif * amzp_intensity * att * sh * amzp_lightCol.rgb) + amzp_lightCol.rgb * sp * att * sh * amzp_intensity;
        amzOutput = float4(clamp(lit, 0.0, 1.0) * c.a, c.a);
    }
    void amzRender() {
        dpInit();
        if ((amzp_showDepth>0.5)) { float d = dep(amzScreenNorm()); amzOutput = float4(float3(d), 1.0); }
        else nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
